(function(){
  const sub = document.querySelector('[data-testid="data-testid drawer subtitle"]');
  if (!sub) return 'not found';
  const fiberKey = Object.keys(sub).find(k => k.startsWith('__reactFiber'));
  if (!fiberKey) return 'no react fiber';
  let fiber = sub[fiberKey];
  let handlers = [];
  let count = 0;
  while (fiber && count < 8) {
    if (fiber.memoizedProps && fiber.memoizedProps.onClick) handlers.push('onClick found at level ' + count);
    if (fiber.memoizedProps && typeof fiber.memoizedProps.onClick === 'function') handlers.push('onClick fn: ' + fiber.memoizedProps.onClick.toString().slice(0, 200));
    fiber = fiber.return;
    count++;
  }
  return handlers.length ? handlers.join(' | ') : 'no onClick handlers found in 8 levels';
})()

(function(){
  const sub = document.querySelector('[data-testid="data-testid drawer subtitle"]');
  if (!sub) return 'not found';
  const fiberKey = Object.keys(sub).find(k => k.startsWith('__reactFiber'));
  if (!fiberKey) return 'no react fiber';
  let fiber = sub[fiberKey];
  let info = [];
  let count = 0;
  while (fiber && count < 12) {
    const props = fiber.memoizedProps || {};
    const propKeys = Object.keys(props).filter(k => typeof props[k] === 'function');
    if (propKeys.length) info.push('level ' + count + ': ' + propKeys.join(','));
    fiber = fiber.return;
    count++;
  }
  return info.length ? info.join(' | ') : 'no function props in 12 levels';
})()

