(function(){
  const sub = document.querySelector('[data-testid="data-testid drawer subtitle"]');
  if (!sub) return 'not found';
  const fiberKey = Object.keys(sub).find(k => k.startsWith('__reactFiber'));
  let fiber = sub[fiberKey];
  // level 3 had onKeyDown/onBlur - get the component name and props
  let count = 0;
  while (fiber && count < 12) {
    if (count === 3) {
      const props = fiber.memoizedProps || {};
      return JSON.stringify({
        propKeys: Object.keys(props),
        onKeyDown: props.onKeyDown ? props.onKeyDown.toString().slice(0, 300) : null,
        element: fiber.elementType ? String(fiber.elementType).slice(0, 200) : null
      });
    }
    fiber = fiber.return;
    count++;
  }
  return 'not found at level 3';
})()

