(function(){
  // The subtitle div is inside a parent with role/tabIndex. Find the parent with onKeyDown/onFocus
  const sub = document.querySelector('[data-testid="data-testid drawer subtitle"]');
  if (!sub) return 'not found';
  let el = sub;
  for (let i = 0; i < 5; i++) {
    if (el.getAttribute && (el.getAttribute('role') || el.getAttribute('tabindex'))) {
      return 'parent with role/tabIndex: ' + el.outerHTML.slice(0, 500);
    }
    el = el.parentElement;
  }
  return 'no parent with role/tabIndex found';
})()

(function(){
  const drawer = document.querySelector('[aria-label="Drawer title Save dashboard"]');
  if (!drawer) return 'no drawer';
  // Get all elements with cursor pointer in the drawer
  const els = Array.from(drawer.querySelectorAll('*')).filter(e => {
    const s = getComputedStyle(e);
    return s.cursor === 'pointer' && e.children.length === 0;
  }).map(e => e.tagName + ': ' + (e.textContent || '').trim().slice(0, 30) + ' | class: ' + e.className.toString().slice(0, 40));
  return JSON.stringify(els);
})()

